const input = $json;

const requiredCodes = [
  'SOURCE_VALIDATION_FAILED',
  'OPENSHORTS_SUBMISSION_FAILED',
  'OPENSHORTS_SUBMISSION_UNKNOWN',
  'TUNNEL_UNREACHABLE',
  'STATUS_RETRIEVAL_FAILED',
  'OPENSHORTS_JOB_FAILED',
  'ORCHESTRATION_TIMEOUT',
  'MALFORMED_STATUS_RESPONSE',
  'NO_CLIPS_RETURNED',
  'TRANSCRIPT_RETRIEVAL_FAILED',
  'CANDIDATE_NORMALIZATION_FAILED',
  'CANDIDATE_SCORING_FAILED',
  'AGGREGATION_FAILED'
];

if (!requiredCodes.includes(input.failure_code)) {
  throw new Error('LOOM_FAILURE_INVALID: Unknown failure_code: ' + input.failure_code);
}

const sanitized = { ...input };
if (sanitized.error_message && typeof sanitized.error_message === 'string') {
  sanitized.error_message = sanitized.error_message.substring(0, 1000);
}
if (sanitized.evidence && sanitized.evidence.headers) {
  delete sanitized.evidence.headers.authorization;
  delete sanitized.evidence.headers['x-n8n-api-key'];
}

return [{ json: sanitized }];

const p = $json;

const title = `🚨 **LOOM Factory Failure:** ${p.failure_code}`;
let text = `${title}\n\n`;
text += `**Stage:** ${p.stage || 'unknown'}\n`;
text += `**Error:** ${p.error_message || 'N/A'}\n`;
text += `**Status:** ${p.http_status || 'N/A'}\n\n`;
text += `**Run ID:** ${p.run_id || 'N/A'}\n`;
text += `**Job ID:** ${p.job_id || 'N/A'} | **Clip ID:** ${p.clip_id || 'N/A'}\n`;
text += `**Attempt:** ${p.attempt || 1}/${p.max_attempts || 1} | **Retryable:** ${p.retryable ? 'Yes' : 'No'}\n`;

return [{ json: { discord_text: text, original_failure: p } }];
